assert.deepEqual(service.patch({ displayName: 'after' }), { displayName: 'after', tags: ['old'] });
assert.deepEqual(service.patch({ tags: ['new'] }), { displayName: 'after', tags: ['new'] });
assert.throws(() => service.patch(null), /invalid profile/);

const originalTags = service.profile.tags;
assert.strictEqual(service.patch({}), service.profile);
assert.strictEqual(service.profile.tags, originalTags);
assert.deepEqual(parseProfile({}), { displayName: { kind: 'keep' }, tags: { kind: 'keep' } });
assert.deepEqual(service.patch({ displayName: null, tags: null }), { displayName: null, tags: [] });
assert.deepEqual(service.patch({ displayName: '  Alice  ', tags: [' one ', 'two\t'] }), {
  displayName: 'Alice', tags: ['one', 'two'],
});
assert.deepEqual(service.patch({ tags: [] }), { displayName: 'Alice', tags: [] });
assert.deepEqual(service.patch(Object.assign(Object.create(null), { tags: ['null-proto'] })), {
  displayName: 'Alice', tags: ['null-proto'],
});
assert.deepEqual(service.patch(Object.create(null)), { displayName: 'Alice', tags: ['null-proto'] });
assert.deepEqual(service.patch({ displayName: ` ${'a'.repeat(40)} `, tags: ['a'.repeat(12), 'b', 'c', 'd', 'e'] }), {
  displayName: 'a'.repeat(40), tags: ['a'.repeat(12), 'b', 'c', 'd', 'e'],
});

const input = Object.freeze({ displayName: '  frozen  ', tags: Object.freeze([' clean ']) });
assert.deepEqual(service.patch(input), { displayName: 'frozen', tags: ['clean'] });
assert.deepEqual(input, { displayName: '  frozen  ', tags: [' clean '] });
assert.notStrictEqual(service.profile.tags, input.tags);
const callerTags = ['caller'];
service.patch({ tags: callerTags });
callerTags.push('later');
assert.deepEqual(service.profile.tags, ['caller']);
service.profile.tags.push('stored');
assert.deepEqual(callerTags, ['caller', 'later']);

const invalidInputs = [
  null, undefined, [], 'text', 1, true, () => {}, new Date(), new String('name'),
  Object.create({ displayName: 'inherited' }),
  { extra: true }, { displayName: 'valid', extra: true },
  { [Symbol('unknown')]: true },
  Object.defineProperty({}, 'hidden', { value: true }),
  { displayName: undefined }, { displayName: 42 }, { displayName: false },
  { displayName: {} }, { displayName: [] }, { displayName: '' },
  { displayName: ' \t\n ' }, { displayName: 'a'.repeat(41) },
  { tags: undefined }, { tags: 'tag' }, { tags: 42 }, { tags: {} },
  { tags: [''] }, { tags: [' \t '] }, { tags: ['a'.repeat(13)] },
  { tags: ['one', 'one'] }, { tags: [' one ', 'one'] },
  { tags: ['a', 'b', 'c', 'd', 'e', 'f'] },
  { tags: [1] }, { tags: ['valid', null] }, { tags: [new String('tag')] },
  { tags: Array(1) },
  { displayName: 'would change', tags: ['valid', 2] },
  { displayName: null, tags: ['duplicate', ' duplicate '] },
  { displayName: ' ', tags: ['would change'] },
];
for (const invalid of invalidInputs) {
  const profile = { displayName: 'before', tags: ['old'] };
  const beforeTags = profile.tags;
  const candidate = new ProfileService(profile);
  assert.throws(() => candidate.patch(invalid), { name: 'Error', message: 'invalid profile' });
  assert.deepEqual(profile, { displayName: 'before', tags: ['old'] });
  assert.strictEqual(profile.tags, beforeTags);
  assert.throws(() => parseProfile(invalid), { name: 'Error', message: 'invalid profile' });
}
